(7143204, 1095341, 117534, '<td valign="top">Oh this is so cool!!!! You really rock these shots!!</td>', 'Oh this is so cool!!!! You really rock these shots!!', '2013-12-16 01:01:51.000000', NULL, 1),
(7143227, 1095102, 96751, '<td valign="top">I like the curves and the dramatic light, but am distracted by the dark areas on the wood and the little white blurs</td>', 'I like the curves and the dramatic light, but am distracted by the dark areas on the wood and the little white blurs', '2013-12-16 01:54:58.000000', NULL, 1),
(7143228, 1095265, 96751, '<td valign="top">Clean, classic</td>', 'Clean, classic', '2013-12-16 01:55:12.000000', NULL, 1),
(7143229, 1095346, 96751, '<td valign="top">Based on the editing and subject, I''d guess Wendy, and a gorgeous one at that. Perhaps a bit too much red in the bg, but what do I know. This will likely ribbon :)</td>', 'Based on the editing and subject, I''d guess Wendy, and a gorgeous one at that. Perhaps a bit too much red in the bg, but what do I know. This will likely ribbon :)', '2013-12-16 01:56:14.000000', NULL, 1),
(7143230, 1095279, 96751, '<td valign="top">Odd, greenish tinge to the yellow</td>', 'Odd, greenish tinge to the yellow', '2013-12-16 01:56:29.000000', NULL, 1),
(7143231, 1094850, 96751, '<td valign="top">Although this may fit in the ratio, the image itself is not particularly interesting to me. Even though it appears to be a flower pushing through the snow, the composition is static</td>', 'Although this may fit in the ratio, the image itself is not particularly interesting to me. Even though it appears to be a flower pushing through the snow, the composition is static', '2013-12-16 01:58:31.000000', NULL, 1),
(7143232, 1095312, 96751, '<td valign="top">Very intriguing bg! Dramatic, compelling lighting/moment</td>', 'Very intriguing bg! Dramatic, compelling lighting/moment', '2013-12-16 01:59:15.000000', NULL, 1),
(7143234, 1095281, 96751, '<td valign="top">Hahaha! Sometimes literal IS interesting</td>', 'Hahaha! Sometimes literal IS interesting', '2013-12-16 01:59:48.000000', NULL, 1),
(7143236, 1095088, 96751, '<td valign="top">Very interesting subject. Seems the animal died while in the velvet phase. I''m sure this fits the spiral just fine, but to my eye, it''s bottom heavy, with too much negative space above, and too crowded near the bottom edge</td>', 'Very interesting subject. Seems the animal died while in the velvet phase. I''m sure this fits the spiral just fine, but to my eye, it''s bottom heavy, with too much negative space above, and too crowded near the bottom edge', '2013-12-16 02:01:09.000000', NULL, 1),
(7143239, 1095113, 96751, '<td valign="top">Lovely b/w still life.</td>', 'Lovely b/w still life.', '2013-12-16 02:01:46.000000', NULL, 1),
(7143240, 1095289, 96751, '<td valign="top">Beautiful. I would hang this on my wall. I hope you''ll share where this is. And why it looks like a giant sand storm is heading towards us</td>', 'Beautiful. I would hang this on my wall. I hope you''ll share where this is. And why it looks like a giant sand storm is heading towards us', '2013-12-16 02:02:29.000000', NULL, 1),
