(7143243, 1094896, 96751, '<td valign="top">I''m fascinated by this place. Hope to visit it some day</td>', 'I''m fascinated by this place. Hope to visit it some day', '2013-12-16 02:03:55.000000', NULL, 1),
(7143245, 1095188, 96751, '<td valign="top">Brilliant!!!!What a fun shot, with terrific geometry and humor</td>', 'Brilliant!!!!What a fun shot, with terrific geometry and humor', '2013-12-16 02:04:50.000000', NULL, 1),
(7143246, 1094736, 96751, '<td valign="top">Looks like this was taken in Bear-land</td>', 'Looks like this was taken in Bear-land', '2013-12-16 02:05:08.000000', NULL, 1),
(7143248, 1095068, 96751, '<td valign="top">Love the colors!!!! Love that the center has even tinier flowers. I wonder, if under a microscope, there were still even tinier flowers</td>', 'Love the colors!!!! Love that the center has even tinier flowers. I wonder, if under a microscope, there were still even tinier flowers', '2013-12-16 02:05:44.000000', NULL, 1),
(7143249, 1095338, 96751, '<td valign="top">Terrific take on the challenge, and great pov. A little overcooked and overcontrasty for me</td>', 'Terrific take on the challenge, and great pov. A little overcooked and overcontrasty for me', '2013-12-16 02:06:16.000000', NULL, 1),
(7143250, 1095195, 96751, '<td valign="top">I have been here!!! What an extraordinary place, and a beautiful capture of it. i love the practically monotone reflection. Perhaps just a bit too much glamour glow</td>', 'I have been here!!! What an extraordinary place, and a beautiful capture of it. i love the practically monotone reflection. Perhaps just a bit too much glamour glow', '2013-12-16 02:07:07.000000', NULL, 1),
(7143253, 1095330, 96751, '<td valign="top">Based on subject and editing alone, I''m going to have to guess this is a Beaumont production. Just a splendid portrait, backlit to perfection</td>', 'Based on subject and editing alone, I''m going to have to guess this is a Beaumont production. Just a splendid portrait, backlit to perfection', '2013-12-16 02:09:02.000000', NULL, 1),
(7143256, 1095020, 96751, '<td valign="top">I have a weakness for long shadows. LOVE the little circle he''s standing in</td>', 'I have a weakness for long shadows. LOVE the little circle he''s standing in', '2013-12-16 02:09:35.000000', NULL, 1),
(7143257, 1095282, 96751, '<td valign="top">That''s an amazing dress, Alessandro</td>', 'That''s an amazing dress, Alessandro', '2013-12-16 02:10:11.000000', NULL, 1),
(7143258, 1095345, 96751, '<td valign="top">I love the idea, the pov, the little people. Just a bit dull, light-wise. The blue cast in the center makes me think you lit this with an LED flashlight</td>', 'I love the idea, the pov, the little people. Just a bit dull, light-wise. The blue cast in the center makes me think you lit this with an LED flashlight', '2013-12-16 02:11:04.000000', NULL, 1),
